import queue, threading
q = queue.Queue()
def worker():
    while True:
        item = q.get()
        if item is None: break       # the pill (or a unique object())
        process(item); q.task_done()
threads = [threading.Thread(target=worker) for _ in range(4)]
for t in threads: t.start()
q.join()                             # drain
for _ in threads: q.put(None)        # one pill per consumer
for t in threads: t.join()

